import type { HTMLAttributes, ReactNode } from 'react';
import '../theme.css';
import './empty-state.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** A 20px line icon for the situation. */
  icon?: ReactNode;
  /** What is empty or what failed, in one sentence. */
  title: ReactNode;
  /** What to do next. */
  description?: ReactNode;
  /** Usually one button. */
  actions?: ReactNode;
  /** 'critical' uses the error colors and role="alert", so the message is announced. */
  tone?: 'neutral' | 'critical';
  /**
   * A dashed frame with the kit background, for use outside a Panel.
   */
  framed?: boolean;
  /** One row: icon, text, action. For narrow lists and side panels. */
  compact?: boolean;
  titleAs?: 'p' | 'h2' | 'h3' | 'h4';
}

export function EmptyState({
  icon,
  title,
  description,
  actions,
  tone = 'neutral',
  framed = false,
  compact = false,
  titleAs: Title = 'p',
  className,
  ...rest
}: EmptyStateProps) {
  return (
    <div
      role={tone === 'critical' ? 'alert' : undefined}
      {...rest}
      className={cx('ws-empty', className)}
      data-tone={tone}
      data-framed={framed ? '' : undefined}
      data-compact={compact ? '' : undefined}
    >
      {icon ? (
        <span className="ws-empty__icon" aria-hidden="true">
          {icon}
        </span>
      ) : null}
      <div className="ws-empty__text">
        <Title className="ws-empty__title">{title}</Title>
        {description ? <p className="ws-empty__description">{description}</p> : null}
      </div>
      {actions ? <div className="ws-empty__actions">{actions}</div> : null}
    </div>
  );
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

.ws-empty {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: var(--ws-space-10) var(--ws-space-5);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  text-align: center;
  animation: ws-empty-in var(--ws-duration) var(--ws-ease) backwards;
}

@keyframes ws-empty-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}

.ws-empty[data-framed] {
  border: 1px dashed var(--ws-color-line-hover);
  border-radius: var(--ws-radius-lg);
  background: var(--ws-color-panel);
}

/* adjusted: the source icon is drawn in the line color (#b5c1cb), which is
   too faint to read. The kit draws it in the muted text color. */
.ws-empty__icon {
  box-sizing: border-box;
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  margin-bottom: var(--ws-space-4);
  border: 1px solid var(--ws-color-line);
  border-radius: 50%;
  background: var(--ws-color-panel);
  color: var(--ws-color-text-muted);
}

.ws-empty__icon svg {
  width: 20px;
  height: 20px;
}

.ws-empty[data-tone='critical'] .ws-empty__icon {
  border-color: var(--ws-color-critical-line);
  background: var(--ws-color-critical-tint);
  color: var(--ws-color-critical-mark);
}

/* min(..., 100%) keeps the text inside narrow containers; anywhere breaks a
   long unspaced string such as a search query echoed in the title. */
.ws-empty__title {
  max-width: min(32ch, 100%);
  overflow-wrap: anywhere;
  margin: 0;
  color: var(--ws-color-text);
  font-size: var(--ws-text-lg);
  font-weight: var(--ws-weight-semibold);
  line-height: var(--ws-leading-tight);
  letter-spacing: var(--ws-tracking-title);
  text-wrap: balance;
}

.ws-empty__description {
  max-width: min(38ch, 100%);
  overflow-wrap: anywhere;
  margin: 6px 0 0;
  color: var(--ws-color-text-muted);
  font-size: var(--ws-text-sm);
  line-height: var(--ws-leading);
  text-wrap: pretty;
}

/* Korean breaks between words. Japanese has no spaces, so it keeps the
   default line breaking (keep-all would leave it no break points). */
.ws-empty:lang(ko) :is(.ws-empty__title, .ws-empty__description) {
  word-break: keep-all;
}

.ws-empty__actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--ws-space-2);
  margin-top: var(--ws-space-5);
}

/* The text wrapper only matters in the compact row. */
.ws-empty__text {
  display: contents;
}

/* Wraps by itself: in a narrow panel the action drops under the text. */
.ws-empty[data-compact] {
  flex-direction: row;
  flex-wrap: wrap;
  gap: var(--ws-space-2) var(--ws-space-3);
  padding: var(--ws-space-3) var(--ws-space-4);
  text-align: start;
}

.ws-empty[data-compact] .ws-empty__icon {
  flex: none;
  width: 32px;
  height: 32px;
  margin: 0;
}

.ws-empty[data-compact] .ws-empty__icon svg {
  width: var(--ws-icon-size);
  height: var(--ws-icon-size);
}

.ws-empty[data-compact] .ws-empty__text {
  display: block;
  flex: 1 1 180px;
  min-width: 0;
}

.ws-empty[data-compact] :is(.ws-empty__title, .ws-empty__description) {
  max-width: none;
}

.ws-empty[data-compact] .ws-empty__title {
  font-size: var(--ws-text-md);
}

.ws-empty[data-compact] .ws-empty__description {
  margin-top: 2px;
}

.ws-empty[data-compact] .ws-empty__actions {
  flex: none;
  margin: 0;
}
